--
-- Table structure for table `nilai_formatif_bulanan`
--

DROP TABLE IF EXISTS `nilai_formatif_bulanan`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `nilai_formatif_bulanan` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kelas_siswa_id` bigint(20) unsigned NOT NULL,
  `mapel_id` bigint(20) unsigned NOT NULL,
  `tahun` smallint(5) unsigned NOT NULL,
  `bulan` tinyint(3) unsigned NOT NULL,
  `nilai` decimal(5,2) DEFAULT NULL,
  `lingkup_materi` varchar(255) DEFAULT NULL,
  `catatan` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idx_formatif_bulanan_unique` (`kelas_siswa_id`,`mapel_id`,`tahun`,`bulan`),
  KEY `idx_formatif_mapel_periode` (`mapel_id`,`tahun`,`bulan`),
  CONSTRAINT `nilai_formatif_bulanan_kelas_siswa_id_foreign` FOREIGN KEY (`kelas_siswa_id`) REFERENCES `kelas_siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `nilai_formatif_bulanan_mapel_id_foreign` FOREIGN KEY (`mapel_id`) REFERENCES `mata_pelajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

