/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `nilai_pembiasaan` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kelas_siswa_id` bigint(20) unsigned NOT NULL,
  `pembiasaan_id` bigint(20) unsigned NOT NULL,
  `periode` enum('sts','sas') NOT NULL,
  `predikat` enum('Sangat Baik','Baik','Cukup','Perlu Bimbingan') NOT NULL DEFAULT 'Baik',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `nilai_pembiasaan_kelas_siswa_id_pembiasaan_id_periode_unique` (`kelas_siswa_id`,`pembiasaan_id`,`periode`),
  KEY `nilai_pembiasaan_pembiasaan_id_foreign` (`pembiasaan_id`),
  CONSTRAINT `nilai_pembiasaan_kelas_siswa_id_foreign` FOREIGN KEY (`kelas_siswa_id`) REFERENCES `kelas_siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `nilai_pembiasaan_pembiasaan_id_foreign` FOREIGN KEY (`pembiasaan_id`) REFERENCES `pembiasaan` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

