--
-- Table structure for table `nilai_rapor_mapel`
--

DROP TABLE IF EXISTS `nilai_rapor_mapel`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `nilai_rapor_mapel` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `kelas_siswa_id` bigint(20) unsigned NOT NULL,
  `mapel_id` bigint(20) unsigned NOT NULL,
  `tahun` int(11) NOT NULL,
  `semester` varchar(20) NOT NULL DEFAULT 'ganjil',
  `rata_formatif` decimal(5,2) DEFAULT NULL,
  `nilai_uts` decimal(5,2) DEFAULT NULL,
  `nilai_uas` decimal(5,2) DEFAULT NULL,
  `nilai_rapor` decimal(5,2) DEFAULT NULL,
  `predikat` varchar(5) DEFAULT NULL,
  `catatan` text DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT 0,
  `locked_at` timestamp NULL DEFAULT NULL,
  `locked_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_nilai_rapor_mapel` (`kelas_siswa_id`,`mapel_id`,`tahun`,`semester`),
  KEY `nilai_rapor_mapel_mapel_id_foreign` (`mapel_id`),
  KEY `nilai_rapor_mapel_locked_by_foreign` (`locked_by`),
  CONSTRAINT `nilai_rapor_mapel_kelas_siswa_id_foreign` FOREIGN KEY (`kelas_siswa_id`) REFERENCES `kelas_siswa` (`id`) ON DELETE CASCADE,
  CONSTRAINT `nilai_rapor_mapel_locked_by_foreign` FOREIGN KEY (`locked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `nilai_rapor_mapel_mapel_id_foreign` FOREIGN KEY (`mapel_id`) REFERENCES `mata_pelajaran` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

